use glam::DVec3;use ingetrazo_gui::{IngeTrazoApp,navigation::{self,Mode}};
fn frame(app:&mut IngeTrazoApp,ctx:&egui::Context,time:f64,events:Vec<egui::Event>){let _=ctx.run(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(800.,600.))),time:Some(time),focused:true,events,..Default::default()},|ctx|{egui::CentralPanel::default().frame(egui::Frame::none()).show(ctx,|ui|{let rect=ui.available_rect_before_wrap();let response=ui.allocate_rect(rect,egui::Sense::click_and_drag());navigation::input(app,ui,rect,&response);});});}
fn button(pos:egui::Pos2,button:egui::PointerButton,pressed:bool)->egui::Event{egui::Event::PointerButton{pos,button,pressed,modifiers:egui::Modifiers::NONE}}
fn main(){let mut rows=vec![];for name in ["split-press-motion","press-motion-one-frame","press-motion-release-one-frame","hover-control-released-before-tick"]{
let mut app=IngeTrazoApp::new();app.camera.aspect=800./600.;app.camera.distance=10.;app.camera.look_from(DVec3::new(0.,0.,1.68),DVec3::Y);app.activate_navigation(Mode::Walk);let ctx=egui::Context::default();frame(&mut app,&ctx,0.,vec![]);let a=egui::pos2(400.,300.);let b=egui::pos2(400.,240.);let press=vec![egui::Event::PointerMoved(a),button(a,egui::PointerButton::Primary,true)];let motion=egui::Event::PointerMoved(b);
if name=="press-motion-release-one-frame"{frame(&mut app,&ctx,0.01,press.into_iter().chain([motion,button(b,egui::PointerButton::Primary,false)]).collect());}
else if name=="split-press-motion"{frame(&mut app,&ctx,0.01,press);frame(&mut app,&ctx,0.02,vec![motion]);}
else if name=="hover-control-released-before-tick"{frame(&mut app,&ctx,0.01,press);let control=egui::Modifiers{ctrl:true,..Default::default()};let _=ctx.run(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(800.,600.))),time:Some(0.02),focused:true,modifiers:control,events:vec![motion],..Default::default()},|ctx|{egui::CentralPanel::default().frame(egui::Frame::none()).show(ctx,|ui|{let rect=ui.available_rect_before_wrap();let response=ui.allocate_rect(rect,egui::Sense::click_and_drag());navigation::input(&mut app,ui,rect,&response);});});}
else{frame(&mut app,&ctx,0.01,press.into_iter().chain([motion]).collect());}
frame(&mut app,&ctx,0.05,vec![]);rows.push(serde_json::json!({"name":name,"eye":app.camera.eye().to_array(),"forward":app.camera.forward().to_array(),"undo":app.undo_stack.len()}));}println!("{}",serde_json::json!({"cases":rows}));}
